import json, datetime
a=json.load(open('data/accounts.json'))
e=json.load(open('fixtures/metering_export.json'))
def D(p):
    s=datetime.date.fromisoformat(p[0]); en=datetime.date.fromisoformat(p[1]); return (en-s).days+1
fails=[]
for x in a:
    d=D(x['period']); c=x['change']
    if not c:
        got=round(x['base_fee'],2)
    else:
        db=c['day']-1; da=d-db
        got=round(x['base_fee']*db/d + c['monthly_fee']*da/d, 2)
    w=e[x['id']]
    if abs(got-w)>0.005: fails.append((x['id'],x['name'],x['period'],x['base_fee'],c,got,w,round(got-w,2)))
print("fails:",len(fails))
for f in fails: print(f)
EOF
